-- Equalizer schema v18: adds 5 original logic-gate circuit diagram
-- questions -- a visual format that did not exist in the bank (the one
-- existing gate-logic question describes the circuit in words only, with
-- no diagram). Each question shows two first-stage gates (fed by inputs
-- A/B and C/D) feeding into a final gate, with an inversion bubble drawn
-- wherever a gate is NAND/NOR. Every question uses a different
-- combination of gate types and input values than the sample this was
-- modeled on and than each other, and every output was computed with a
-- full boolean truth-table evaluation (shown in each explanation), not
-- eyeballed from the diagram.
--
-- Since a single-gate-output question only ever has two real answers (0
-- or 1), the options follow the same four-choice format the bank's
-- existing text-only gate question already uses: "0", "1", "either 0 or
-- 1", "cannot be determined" -- rather than inventing four numeric
-- distractors for what is fundamentally a binary result.
--
-- Per instruction, this migration does NOT remove any duplicate
-- questions -- it only adds, bringing the total question count from 220
-- (after migrations_v17.sql) to 225.

insert into public.questions (subject, category, question, options, answer_index, explanation, diagram_svg) values

('acl', 'Logic/Reasoning', 'When A = 1, B = 1, C = 0 and D = 1, what will be the output?',
 '["0", "1", "either 0 or 1", "cannot be determined"]'::jsonb,
 1, 'Top gate: AND(A, B) = AND(1, 1) = 1. Bottom gate: AND(C, D) = AND(0, 1) = 0. Final gate: OR(1, 0) = 1. The output is 1.',
 '<svg viewBox="0 0 420 230" xmlns="http://www.w3.org/2000/svg" fill="none" stroke="currentColor"><text x="10" y="45" font-size="16" font-weight="bold" text-anchor="start" fill="currentColor">A</text><line x1="25" y1="40" x2="100" y2="40" stroke="currentColor" stroke-width="2"/><circle cx="25" cy="40" r="3" fill="currentColor"/><text x="10" y="75" font-size="16" font-weight="bold" text-anchor="start" fill="currentColor">B</text><line x1="25" y1="70" x2="100" y2="70" stroke="currentColor" stroke-width="2"/><circle cx="25" cy="70" r="3" fill="currentColor"/><g transform="translate(100,20)"><path d="M0,0 L30,0 A25,25 0 0 1 30,50 L0,50 Z" fill="none" stroke="currentColor" stroke-width="2"/></g><line x1="160" y1="45" x2="175" y2="45" stroke="currentColor" stroke-width="2"/><circle cx="175" cy="45" r="3" fill="currentColor"/><line x1="175" y1="45" x2="175" y2="90" stroke="currentColor" stroke-width="2"/><line x1="175" y1="90" x2="260" y2="90" stroke="currentColor" stroke-width="2"/><circle cx="260" cy="90" r="3" fill="currentColor"/><text x="10" y="165" font-size="16" font-weight="bold" text-anchor="start" fill="currentColor">C</text><line x1="25" y1="160" x2="100" y2="160" stroke="currentColor" stroke-width="2"/><circle cx="25" cy="160" r="3" fill="currentColor"/><text x="10" y="195" font-size="16" font-weight="bold" text-anchor="start" fill="currentColor">D</text><line x1="25" y1="190" x2="100" y2="190" stroke="currentColor" stroke-width="2"/><circle cx="25" cy="190" r="3" fill="currentColor"/><g transform="translate(100,140)"><path d="M0,0 L30,0 A25,25 0 0 1 30,50 L0,50 Z" fill="none" stroke="currentColor" stroke-width="2"/></g><line x1="160" y1="165" x2="175" y2="165" stroke="currentColor" stroke-width="2"/><circle cx="175" cy="165" r="3" fill="currentColor"/><line x1="175" y1="165" x2="175" y2="120" stroke="currentColor" stroke-width="2"/><line x1="175" y1="120" x2="260" y2="120" stroke="currentColor" stroke-width="2"/><circle cx="260" cy="120" r="3" fill="currentCol